# Get release dates for all liked songs.
from datetime import datetime
song_info = {}
for s in liked:
    detail = apis.spotify.show_song(song_id=s['song_id'])
    rd = detail['release_date']
    # parse month
    try:
        dt = datetime.strptime(rd, '%Y-%m-%d')
    except Exception:
        dt = datetime.strptime(rd, '%Y-%m')
    month_str = dt.strftime('%m/%Y')
    song_info[s['title']] = {
        'artists': ', '.join(a['name'] for a in s['artists']),
        'month': month_str
    }
    print(s['title'], rd, month_str)
print(song_info)

